python3 - <<'PY'
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
from pathlib import Path
path=Path('/root/output/result.xlsx')
print(f'Result exists: {path.exists()} size={path.stat().st_size if path.exists() else None}')
wb=load_workbook(path, keep_vba=False, data_only=False)
print('Sheet names:', wb.sheetnames)
assert wb.sheetnames == ['Task','Data'], f'Unexpected sheets: {wb.sheetnames}'
ws=wb['Task']

def coords_for_range(row_start,row_end,col_start=8,col_end=12):
    for r in range(row_start,row_end+1):
        for c in range(col_start,col_end+1):
            yield f'{get_column_letter(c)}{r}'

ranges=[('lookup committed',12,17),('lookup opex',19,24),('lookup budget base',26,31),('net buffer',35,40),('stats',42,47),('weighted mean',50,50)]
errors=[]
counts={}
for name, r1, r2 in ranges:
    count=0
    for coord in coords_for_range(r1,r2):
        v=ws[coord].value
        count+=1
        if not (isinstance(v,str) and v.startswith('=')):
            errors.append((coord,v))
    counts[name]=count
print('Formula cell counts checked:', counts)
if errors:
    print('Non-formula cells found:', errors)
    raise SystemExit(1)

print('\nSample formulas from each block:')
samples=['H12','I12','L17','H19','L24','H26','L31','H35','I36','L40','H42','I43','J44','K45','L46','H47','H50','L50']
for coord in samples:
    print(f'{coord}: {ws[coord].value}')

# Verify exact expected formulas for representative formulas and all generated formulas structurally.
for row in list(range(12,18))+list(range(19,25))+list(range(26,32)):
    for c in range(8,13):
        col=get_column_letter(c)
        expected=f'=INDEX(Data!$H$21:$L$38, MATCH($D{row}, Data!$D$21:$D$38, 0), MATCH({col}$10, Data!$H$4:$L$4, 0))'
        if ws.cell(row,c).value != expected:
            raise AssertionError(f'{col}{row} expected {expected} got {ws.cell(row,c).value}')
for offset,row in enumerate(range(35,41)):
    for c in range(8,13):
        col=get_column_letter(c)
        expected=f'=({col}{12+offset}-{col}{19+offset})/{col}{26+offset}*100'
        if ws.cell(row,c).value != expected:
            raise AssertionError(f'{col}{row} expected {expected} got {ws.cell(row,c).value}')
expected_stats={42:'MIN',43:'MAX',44:'MEDIAN',45:'AVERAGE'}
for c in range(8,13):
    col=get_column_letter(c)
    for row, fn in expected_stats.items():
        expected=f'={fn}({col}35:{col}40)'
        if ws.cell(row,c).value != expected:
            raise AssertionError(f'{col}{row} expected {expected} got {ws.cell(row,c).value}')
    if ws.cell(46,c).value != f'=PERCENTILE.INC({col}35:{col}40,0.25)':
        raise AssertionError(f'{col}46 wrong: {ws.cell(46,c).value}')
    if ws.cell(47,c).value != f'=PERCENTILE.INC({col}35:{col}40,0.75)':
        raise AssertionError(f'{col}47 wrong: {ws.cell(47,c).value}')
    expected=f'=SUMPRODUCT({col}35:{col}40,{col}26:{col}31)/SUM({col}26:{col}31)'
    if ws.cell(50,c).value != expected:
        raise AssertionError(f'{col}50 expected {expected} got {ws.cell(50,c).value}')

print('\nVerification passed: formulas exist as strings in all target cells, workbook is readable, no extra sheets added.')
